import assert from 'node:assert/strict';
import { createPushGate } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-haiku/work/courier-g2-3/bot.mjs';

const tokyo = (iso) => new Date(iso); // helper for readability
const base = { id: 'u_8841', timeZone: 'Asia/Tokyo', quietStart: '22:00', quietEnd: '07:00', dailyCap: 3 };

// 1. Allowed in daytime, reason null
{
  const g = createPushGate();
  assert.deepEqual(g.attempt(base, tokyo('2026-10-22T04:00:00Z')), { allowed: true, reason: null }); // 13:00 Tokyo
}
// 2. Quiet hours cross midnight, using user's zone (23:30 Tokyo = 14:30Z)
{
  const g = createPushGate();
  assert.deepEqual(g.attempt(base, tokyo('2026-10-22T14:30:00Z')), { allowed: false, reason: 'quiet_hours' });
  // 06:59 Tokyo = 21:59Z previous day -> still quiet
  assert.equal(g.attempt(base, tokyo('2026-10-21T21:59:00Z')).reason, 'quiet_hours');
  // 07:00 Tokyo = 22:00Z -> not quiet
  assert.equal(g.attempt(base, tokyo('2026-10-21T22:00:00Z')).allowed, true);
}
// 3. Same instant, server in UTC is 14:00 but Tokyo is 23:00 -> quiet
{
  const g = createPushGate();
  assert.equal(g.attempt(base, tokyo('2026-10-22T14:00:00Z')).reason, 'quiet_hours');
}
// 4. Non-wrapping quiet window (13:00-14:00 local, New York)
{
  const g = createPushGate();
  const ny = { id: 'ny', timeZone: 'America/New_York', quietStart: '13:00', quietEnd: '14:00', dailyCap: 9 };
  // 13:30 EDT (Oct 22 is still EDT) = 17:30Z
  assert.equal(g.attempt(ny, tokyo('2026-10-22T17:30:00Z')).reason, 'quiet_hours');
  // 14:00 EDT = 18:00Z -> allowed
  assert.equal(g.attempt(ny, tokyo('2026-10-22T18:00:00Z')).allowed, true);
}
// 5. Daily cap counted per local calendar day, spacing 1h
{
  const g = createPushGate();
  const u = { ...base, dailyCap: 2 };
  assert.equal(g.attempt(u, tokyo('2026-10-22T01:00:00Z')).allowed, true); // 10:00 JST
  assert.equal(g.attempt(u, tokyo('2026-10-22T03:00:00Z')).allowed, true); // 12:00 JST
  assert.equal(g.attempt(u, tokyo('2026-10-22T05:00:00Z')).reason, 'daily_cap_reached'); // 14:00 JST
  // Next local day (Oct 23 10:00 JST = Oct 23 01:00Z): cap reset
  assert.equal(g.attempt(u, tokyo('2026-10-23T01:00:00Z')).allowed, true);
}
// 6. Local day boundary: 23:30 JST Oct 22 (quiet, so use a non-quiet user) vs 00:30 JST Oct 23
{
  const g = createPushGate();
  const u = { ...base, quietStart: '02:00', quietEnd: '03:00', dailyCap: 1 };
  assert.equal(g.attempt(u, tokyo('2026-10-22T14:30:00Z')).allowed, true); // 23:30 JST Oct 22
  // 00:30 JST Oct 23 = 15:30Z Oct 22: new local day, but only 1h later -> too_soon? gap = 60min exactly, not < 60 -> allowed
  assert.equal(g.attempt(u, tokyo('2026-10-22T15:30:00Z')).allowed, true);
}
// 7. Spacing blocks bursts
{
  const g = createPushGate();
  assert.equal(g.attempt(base, tokyo('2026-10-22T04:00:00Z')).allowed, true);
  assert.equal(g.attempt(base, tokyo('2026-10-22T04:30:00Z')).reason, 'too_soon');
  assert.equal(g.attempt(base, tokyo('2026-10-22T05:00:00Z')).allowed, true);
}
// 8. Blocked attempts do not count against the cap
{
  const g = createPushGate();
  const u = { ...base, dailyCap: 1 };
  assert.equal(g.attempt(u, tokyo('2026-10-22T14:30:00Z')).reason, 'quiet_hours');
  assert.equal(g.attempt(u, tokyo('2026-10-22T04:00:00Z')).allowed, true);
}
// 9. dailyCap 0 always blocks
{
  const g = createPushGate();
  assert.equal(g.attempt({ ...base, dailyCap: 0 }, tokyo('2026-10-22T04:00:00Z')).reason, 'daily_cap_reached');
}
// 10. Independent gates and per-user history
{
  const g1 = createPushGate();
  const g2 = createPushGate();
  assert.equal(g1.attempt(base, tokyo('2026-10-22T04:00:00Z')).allowed, true);
  assert.equal(g2.attempt(base, tokyo('2026-10-22T04:00:00Z')).allowed, true);
  assert.equal(g1.attempt({ ...base, id: 'other' }, tokyo('2026-10-22T04:10:00Z')).allowed, true);
}
// 11. Per-call settings are used: cap changes apply immediately
{
  const g = createPushGate();
  assert.equal(g.attempt({ ...base, dailyCap: 5 }, tokyo('2026-10-22T04:00:00Z')).allowed, true);
  assert.equal(g.attempt({ ...base, dailyCap: 1 }, tokyo('2026-10-22T06:00:00Z')).reason, 'daily_cap_reached');
}
// 12. DST: America/New_York spring forward 2026-03-08 02:00 -> 03:00
{
  const g = createPushGate();
  const ny = { id: 'dst', timeZone: 'America/New_York', quietStart: '22:00', quietEnd: '07:00', dailyCap: 5 };
  // 2026-03-08 03:30 EDT = 07:30Z -> not quiet
  assert.equal(g.attempt(ny, tokyo('2026-03-08T07:30:00Z')).allowed, true);
  // 2026-03-08 06:30 EDT = 10:30Z -> not quiet (still before 7? no, 06:30 < 07:00 -> quiet)
  assert.equal(g.attempt({ ...ny, id: 'dst2' }, tokyo('2026-03-08T10:30:00Z')).reason, 'quiet_hours');
}
// 13. Invalid input throws TypeError
{
  const g = createPushGate();
  assert.throws(() => g.attempt({ ...base, quietStart: '25:00' }, new Date()), TypeError);
  assert.throws(() => g.attempt({ ...base, dailyCap: -1 }, new Date()), TypeError);
  assert.throws(() => g.attempt({ ...base, timeZone: 'Mars/Olympus' }, new Date()), TypeError);
  assert.throws(() => g.attempt(base, new Date('nope')), TypeError);
}
console.log('all checks passed');
EOF
